#include &lt;iostream&gt; using namespace std; int main() { for (int i = 2; i &lt;= 100; i++) { // 枚举1到100的数 bool flag = true; // 是素数的标志 for (int j = 2; j &lt; i; j++) { // 枚举2到i-1的数 // 如果j整除i，则i不是素数，将标志修改为false，退出内层的循环 if (i % j == 0) { flag = false; // i被整除，不是素数 break; // 找到一个因子，即可退出本层循环 } } if (!flag) continue; // 如果标志为false，不输出 cout &lt;&lt; i &lt;&lt; endl; // 不是素数时不输出 } return 0; } 基于哨兵的循环 #include &lt;iostream&gt; using namespace std; int main() { char ch; int numVowel = 0, numCons = 0, numSpace = 0, numDigit = 0, numOther = 0; cout &lt;&lt; &#34;请输入句子：&#34;; cin.get(ch); // 读入一个字符，必须用get函数 while (ch != &#39;.&#39;) { // 处理每个字符 if (ch &gt;= &#39;A&#39; &amp;&amp; ch &lt;= &#39;Z&#39;) // 大写字母转成小写字母 ch = ch - &#39;A&#39; + &#39;a&#39;; if (ch &gt;= &#39;a&#39; &amp;&amp; ch &lt;= &#39;z&#39;) if (ch == &#39;a&#39; || ch == &#39;e&#39; || ch == &#39;i&#39; || ch == &#39;o&#39; || ch == &#39;u&#39;) ++numVowel; else ++numCons; else if (ch == &#39; &#39;) ++numSpace; else if (ch &gt;= &#39;0&#39; &amp;&amp; ch &lt;= &#39;9&#39;) ++numDigit; else ++numOther; cin.get(ch); // 读入一个字符 } cout &lt;&lt; &#34;元音字母数：&#34; &lt;&lt; numVowel &lt;&lt; endl; cout &lt;&lt; &#34;辅音字母数：&#34; &lt;&lt; numCons &lt;&lt; endl; cout &lt;&lt; &#34;空格数：&#34; &lt;&lt; numSpace &lt;&lt; endl; cout &lt;&lt; &#34;数字字符数：&#34; &lt;&lt; numDigit &lt;&lt; endl; cout &lt;&lt; &#34;其他字符数：&#34; &lt;&lt; numOther &lt;&lt; endl; return 0; } 将读取一个字符的工作放在while中进行，使程序更加简洁。

循环结构 循环结构用于重复执行一段逻辑。本章整理 for、while、do while、嵌套循环和哨兵循环等写法。
for 循环执行顺序 for (表达式1; 表达式2; 表达式3) 的执行顺序是：
先执行一次表达式 1，通常用于初始化循环变量。 判断表达式 2，如果为真则进入循环体。 执行循环体语句。 执行表达式 3，通常用于更新循环变量。 回到第 2 步继续判断。 示例：
int sum = 0; for (int i = 1; i &lt;= 100; ++i) { sum += i; } 循环变量初值、终止条件和更新方向必须配套，否则容易出现死循环或边界错误。
表达式1执行几次？ 1 表达式2执行几次？ 11 表达式3执行几次？ 10 for内循环体执行了几次？ 10 循环体结束后打印i=？ 11
初值为1，公差为5的等差数列求和，并要求数列最大值小于101，和小于500， 逗号表达式
斐波那契数列的前n项
#include &lt;iostream&gt; using namespace std; int main() { int n; cin &gt;&gt; n; unsigned long long first = 1, second = 1; unsigned long long next; if (n == 1) { cout &lt;&lt; first &lt;&lt; &#34; &#34;; } else if (n == 2) { cout &lt;&lt; first &lt;&lt; &#34; &#34; &lt;&lt; second &lt;&lt; &#34; &#34;; } else { cout &lt;&lt; first &lt;&lt; &#34; &#34; &lt;&lt; second &lt;&lt; &#34; &#34;; for (int i = 1; i &lt;= n - 2; i++) { next = first + second; first = second; second = next; cout &lt;&lt; next &lt;&lt; &#34; &#34;; } } return 0; } 求e^x^的值 $$ e^x = \sum_{n=0}^{\infty} \frac{x^n}{n!} = 1 + \frac{x}{1!} + \frac{x^2}{2!} + \frac{x^3}{3!} + \cdots + \frac{x^n}{n!} + \cdots $$
#include &lt;iostream&gt; using namespace std; int main() { double x, p=1, ex=0; cin &gt;&gt; x; int i = 1; while (p &gt;= 1e-6) { ex += p; p = p * x / i; i++; } cout &lt;&lt; ex &lt;&lt; endl; return 0; } 或者
#include &lt;iostream&gt; #include &lt;cmath&gt; using namespace std; int Factorial(int n) { if (n == 0) return 1; else return n * Factorial(n - 1); } int main() { double x, p = 1, ex = 0; cin &gt;&gt; x; for (int i = 0; p &gt; 1e-6; i++) { p = pow(x, i) / Factorial(i); ex += p; } cout &lt;&lt; ex &lt;&lt; endl; return 0; } #include &lt;iostream&gt; using namespace std; int main() { int a; int i = 0; while (cin &gt;&gt; a) i++; cout &lt;&lt; i &lt;&lt; endl; return 0; } 问题描述： 阿姆斯特朗数指一个n位数，他的每一位数字的n（暂时假定为3）次幂之和等于它本身。例如：153 = 1^3 + 5^3 + 3^3。编写一个程序，从用户获得正整数start和end，找出并输出这两个和之间所有的阿姆斯特朗数
#include &lt;iostream&gt; using namespace std; int main() { int start, end; cin &gt;&gt; start &gt;&gt; end; for (int i = start; i &lt;= end; ++i) { int cur_num = i; int sum = 0; while (cur_num != 0) { int digit = cur_num % 10; sum += (digit * digit * digit); cur_num = (cur_num - digit) / 10; } if (sum == i) cout &lt;&lt; i &lt;&lt; endl; } return 0; } 或者
#include &lt;iostream&gt; using namespace std; int main() { int start, end; cin &gt;&gt; start &gt;&gt; end; for (int i = start; i &lt;= end; ++i) { int cur_num = i; int sum = 0; while (true) { int digit = cur_num % 10; sum += (digit * digit * digit); cur_num = (cur_num - digit) / 10; if (cur_num == 0) break; } if (sum == i) cout &lt;&lt; i &lt;&lt; endl; } return 0; } 如何跳出外层循环？设置一个布尔型变量flag
