#include &lt;iostream&gt; using namespace std; int main() { char sentence[80], prev = &#39; &#39;; // prev表示当前字符的前一字符 int num = 0; cin.getline(sentence, 80); for (int i = 0; sentence[i] != &#39;\0&#39;; ++i) { if (prev == &#39; &#39; &amp;&amp; sentence[i] != &#39; &#39;) ++num; prev = sentence[i]; } cout &lt;&lt; num &lt;&lt; endl; return 0; } 输入一个字符串，以回车为结尾，输出每个字符在字母表中的序号。对于非英文字母输出0。例如输入为&quot;acbf8g&quot;，输出为1 3 2 6 0 7
方法一
#include &lt;iostream&gt; using namespace std; int main() { char ch; while ((ch = cin.get()) != &#39;\n&#39;) { if (ch &gt;= &#39;A&#39; &amp;&amp; ch &lt;= &#39;Z&#39;) ch = ch - &#39;A&#39; + &#39;a&#39;; if (ch &gt;= &#39;a&#39; &amp;&amp; ch &lt;= &#39;z&#39;) cout &lt;&lt; ch - &#39;a&#39; + 1 &lt;&lt; &#39; &#39;; else cout &lt;&lt; 0 &lt;&lt; &#39; &#39;; } cout &lt;&lt; endl; return 0; } 注意(ch = cin.get()) != '\n'的用法！
方法二
#include &lt;iostream&gt; using namespace std; int main() { char ch[80]; int i; cin.getline(ch, 80); for (i = 0; ch[i] != &#39;\0&#39;; i++) { if (ch[i] &gt;= &#39;A&#39; &amp;&amp; ch[i] &lt;= &#39;Z&#39;) ch[i] = ch[i] - &#39;A&#39; + &#39;a&#39;; if (ch[i] &gt;= &#39;a&#39; &amp;&amp; ch[i] &lt;= &#39;z&#39;) cout &lt;&lt; ch[i] - &#39;a&#39; + 1 &lt;&lt; &#39; &#39;; else cout &lt;&lt; 0 &lt;&lt; &#39; &#39;; } cout &lt;&lt; endl; return 0; } 编写一个程序，将输入的字符串表示的数字字符转换成double型的数值，如输入的是&quot;123.456&quot;，输出为123.456
#include &lt;iostream&gt; using namespace std; int main() { char ch[100]; double num = 0; bool flag = false; // 用于判断是否有小数点 int pos = 0; // 小数点位置 cin.getline(ch, 100); for(int i = 0; ch[i] != &#39;\0&#39;; i++) { if(ch[i] &gt;= &#39;0&#39; &amp;&amp; ch[i] &lt;= &#39;9&#39;) { num = num * 10 + ch[i] - &#39;0&#39;; } if(flag) pos++; if(ch[i] == &#39;.&#39;) flag = true; } while(pos-- != 0) num /= 10; cout &lt;&lt; num &lt;&lt; endl; return 0; } 注意bool flag和pos--的使用!
输入奇数个数（小于20个），这些数中，有一个数只出现了一次，找出该数（默认输入符合条件）。 例如： 输入： 2 2 1 输出： 1
方法一
#include &lt;iostream&gt; using namespace std; int main() { char ch[100]; cin.getline(ch, 100); int num[20]; int count = 0; // 解析数字 for (int i = 0; ch[i] != &#39;\0&#39;; ) { if (ch[i] == &#39; &#39;) { i++; continue; } int val = 0; while (ch[i] &gt;= &#39;0&#39; &amp;&amp; ch[i] &lt;= &#39;9&#39;) { val = val * 10 + (ch[i] - &#39;0&#39;); i++; } num[count++] = val; } // 查找只出现一次的数 for (int i = 0; i &lt; count; i++) { bool flag = true; for (int j = 0; j &lt; count; j++) { if (i != j &amp;&amp; num[i] == num[j]) { flag = false; break; } } if (flag) { cout &lt;&lt; num[i] &lt;&lt; endl; break; } } return 0; } 方法二
将字符串反转但不反转单个单词。
编程要求 根据提示，在右侧编辑器补充代码
测试说明 平台会对你编写的代码进行测试：
输入描述： 用户输入一个字符串，要求首尾无空格，单词之间有一个空格，例如： I am a student
输出描述： 将字符串反转但不反转单个单词，并在屏幕输出 student a am I
#include &lt;iostream&gt; #include &lt;cstring&gt; using namespace std; void reverse(char s[], int left, int right) { right--; while (left &lt; right) { char temp = s[left]; s[left] = s[right]; s[right] = temp; left++; right--; } } int main() { char ch[500]; cin.getline(ch, 500); reverse(ch, 0, strlen(ch)); int start = 0; for (int i = start; i &lt;= strlen(ch); i++) { if (ch[i] == &#39; &#39; || ch[i] == &#39;\0&#39;) { reverse(ch, start, i); start = i+1; } } cout &lt;&lt; ch; return 0; } #include &lt;iostream&gt; using namespace std; int main() { int a=0, b=0; int cal = 0; char ch[100]; cin.getline(ch, 100); for(int i = 0; ch[i]; i++) { if(cal == 0 &amp;&amp; ch[i] &gt;= &#39;0&#39; &amp;&amp; ch[i] &lt;= &#39;9&#39;) { a = a * 10 + ch[i] - &#39;0&#39;; } else if(ch[i] == &#39;+&#39;) cal = 1; else if(ch[i] == &#39;-&#39;) cal = 2; else if(ch[i] == &#39;*&#39;) cal = 3; else if(ch[i] == &#39;/&#39;) cal = 4; else if(cal != 0 &amp;&amp; ch[i] &gt;= &#39;0&#39; &amp;&amp; ch[i] &lt;= &#39;9&#39;) { b = b * 10 + ch[i] - &#39;0&#39;; } } switch (cal) { case 1: cout &lt;&lt; a + b; break; case 2: cout &lt;&lt; a - b; break; case 3: cout &lt;&lt; a * b; break; case 4: cout &lt;&lt; a / b; break; } return 0; }

